    MONGSE_imageV31234 = MONGSE_spriteV31234
      ? MONGSE_queueImage(MONGSE_imagesV31234, MONGSE_spriteV31234)
      : null;
  if (!(MONGSE_imageV31234?.complete && MONGSE_imageV31234.naturalWidth > 0))
    return !1;
