  return {id:row.id,zone:row.zone,path:row.path,pose,frame,x:p.x,y:p.y,flip,scale,headFootHeight:(frame.foot[1]-frame.head[1])*scale,bounds:{left:Math.min(...points.map(q=>q.x)),right:Math.max(...points.map(q=>q.x)),top:Math.min(...points.map(q=>q.y)),bottom:Math.max(...points.map(q=>q.y))}};
