/* HAPIL v3.14 FINAL RC9 — scale only verified clone bodies, never their UI.
 * The active Yn body draw consumes prepareCloneVisual; simulation stats remain
 * owned by the original enemy and projectile pipelines.
 */
(() => {
  "use strict";
  if (typeof window === "undefined") return;

  const MAX_CLONE_RENDER_SCALE = 4.4;
  const bossTemplates = new Map();
  const metrics = { candidates: 0, scaled: 0, missingOwner: 0, rejectedBossClass: 0 };
  for (const zone of Object.values(N ?? {})) {
    for (const actor of zone?.enemies ?? []) {
      if (actor?.boss === true && actor?.id) bossTemplates.set(String(actor.id), actor);
    }
  }

  function looksLikeBossClone(actor) {
    if (!actor || actor.episodeBossSummon !== true) return false;
    if (
      actor.envyHallucination === true ||
      actor.bossClone === true ||
      actor.mirrorClone === true ||
      actor.afterimageClone === true
    ) return true;
    // The Last-301 pool reuses the Fallen Angel Knight artwork as actual split
    // bodies. Generic 'echo/잔영' names also belong to unrelated themed mobs.
    return actor.summonOwnerId === "l301-boss" &&
      actor.kind === "fallen" &&
      /^타락천사 분열체(?:\s+[IVX]+)?$/.test(String(actor.name ?? "")) &&
      /Monster_FallenAngelKnight_(?:MoveSide|AttackSide|Guard)\.png$/.test(String(actor.sprite ?? ""));
  }

  function actorDrawHeight(actor) {
    if (!actor || typeof Ge !== "function") return 0;
    const base = Number(Ge(actor.kind, actor.boss === true,
      actor.midboss === true, actor.elite === true, actor.scale));
    const phase = typeof MONGSE_phaseScale === "function"
      ? Number(MONGSE_phaseScale(actor)) : 1;
    const rankFactor = actor.boss === true ? 1.1 : 1;
    const height = base * (Number.isFinite(phase) ? phase : 1) * rankFactor;
    return Number.isFinite(height) && height > 0 ? height : 0;
  }

  function prepareCloneVisual(actor) {
    if (actor?.bossCloneVisualV314RC9 === true)
      return Number(actor.bossCloneVisualScaleV314RC9 ?? 1);
    if (!looksLikeBossClone(actor)) return 1;
    metrics.candidates += 1;
    if (actor.boss === true || actor.midboss === true) {
      metrics.rejectedBossClass += 1;
      return 1;
    }
    const owner = bossTemplates.get(String(actor.summonOwnerId ?? ""));
    if (!owner) {
      metrics.missingOwner += 1;
      return 1;
    }
    const ownerHeight = actorDrawHeight(owner);
    const cloneHeight = actorDrawHeight(actor);
    if (!(ownerHeight > 0) || !(cloneHeight > 0)) {
      metrics.missingOwner += 1;
      return 1;
    }
    const scale = Math.max(1, Math.min(MAX_CLONE_RENDER_SCALE, ownerHeight / cloneHeight));
    Object.assign(actor, {
      bossCloneVisualV314RC9: true,
      bossCloneVisualScaleV314RC9: scale,
      bossCloneVisualOwnerV314RC9: String(owner.id),
      bossCloneVisualTargetHeightV314RC9: ownerHeight,
      bossCloneVisualBaseHeightV314RC9: cloneHeight,
    });
    metrics.scaled += 1;
    return scale;
  }

  function auditMob(state, actor) {
    return Object.freeze({
      inEnemyList: Array.isArray(state?.enemies) && state.enemies.includes(actor),
      episodeBossSummon: actor?.episodeBossSummon === true,
      ordinaryMobClass: actor?.boss !== true && actor?.midboss !== true,
      positiveHp: Number.isFinite(Number(actor?.hp)) && Number(actor.hp) > 0,
      validMaxHp: Number.isFinite(Number(actor?.maxHp)) && Number(actor.maxHp) >= Number(actor.hp),
    });
  }

  window.__HAPIL_BOSS_CLONE_VISUAL_V314RC9__ = Object.freeze({
    version: "3.14-FINAL-RC9",
    installed: typeof Yn === "function",
    maxRenderScale: MAX_CLONE_RENDER_SCALE,
    looksLikeBossClone,
    actorDrawHeight,
    prepareCloneVisual,
    auditMob,
    metrics: () => Object.freeze({ ...metrics }),
    scope: "verified boss-clone body size and target pointer only; no Canvas-wide scaling",
  });
})();

